import java.util.*;
import java.io.*;

public class Main {
    static class FlowGraph {
        int n;
        List<int[]> edgesStorage;
        List<Edge>[] adjacency;
        int[] potential;
        int[] prevVertex;
        int[] prevEdge;

        @SuppressWarnings("unchecked")
        public FlowGraph(int n) {
            this.n = n;
            edgesStorage = new ArrayList<>();
            adjacency = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                adjacency[i] = new ArrayList<>();
            }
        }

        public int addEdge(int u, int v, int capacity, int cost) {
            int index = edgesStorage.size();
            edgesStorage.add(new int[]{u, adjacency[u].size()});
            adjacency[u].add(new Edge(v, adjacency[v].size(), capacity, cost));
            adjacency[v].add(new Edge(u, adjacency[u].size() - 1, 0, -cost));
            return index;
        }

        class Edge {
            int to;
            int rev;
            int cap;
            int cst;

            public Edge(int to, int rev, int cap, int cst) {
                this.to = to;
                this.rev = rev;
                this.cap = cap;
                this.cst = cst;
            }
        }

        public Edge getEdge(int i) {
            int[] eInfo = edgesStorage.get(i);
            Edge e = adjacency[eInfo[0]].get(eInfo[1]);
            Edge re = adjacency[e.to].get(e.rev);
            return new Edge(eInfo[0], e.to, e.cap + re.cap, e.cst);
        }

        public List<Edge> allEdges() {
            List<Edge> result = new ArrayList<>();
            for (int i = 0; i < edgesStorage.size(); i++) {
                int[] eInfo = edgesStorage.get(i);
                Edge e = adjacency[eInfo[0]].get(eInfo[1]);
                Edge re = adjacency[e.to].get(e.rev);
                result.add(new Edge(eInfo[0], e.to, e.cap + re.cap, e.cst));
            }
            return result;
        }

        private boolean calculateShortestPath(int s, int t) {
            int[] dist = new int[n];
            Arrays.fill(dist, Integer.MAX_VALUE);
            prevVertex = new int[n];
            prevEdge = new int[n];
            boolean[] visited = new boolean[n];
            PriorityQueue<int[]> heap = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
            dist[s] = 0;
            heap.offer(new int[]{0, s});
            while (!heap.isEmpty()) {
                int[] current = heap.poll();
                int d = current[0];
                int v = current[1];
                if (visited[v]) continue;
                visited[v] = true;
                if (v == t) break;
                for (int i = 0; i < adjacency[v].size(); i++) {
                    Edge e = adjacency[v].get(i);
                    if (visited[e.to] || e.cap == 0) continue;
                    int nd = d + e.cst;
                    if (dist[e.to] > nd) {
                        dist[e.to] = nd;
                        prevVertex[e.to] = v;
                        prevEdge[e.to] = i;
                        heap.offer(new int[]{nd, e.to});
                    }
                }
            }
            if (!visited[t]) return false;
            potential = new int[n];
            for (int v = 0; v < n; v++) {
                if (visited[v]) {
                    potential[v] -= dist[t];
                }
            }
            return true;
        }

        public List<long[]> computeFlow(int s, int t, long maxFlow) {
            long flow = 0;
            long totalCost = 0;
            List<long[]> results = new ArrayList<>();
            results.add(new long[]{flow, totalCost});
            while (flow < maxFlow) {
                if (!calculateShortestPath(s, t)) break;
                long c = maxFlow - flow;
                int v = t;
                while (v != s) {
                    int u = prevVertex[v];
                    Edge e = adjacency[u].get(prevEdge[v]);
                    c = Math.min(c, e.cap);
                    v = u;
                }
                v = t;
                while (v != s) {
                    int u = prevVertex[v];
                    Edge e = adjacency[u].get(prevEdge[v]);
                    e.cap -= c;
                    adjacency[v].get(e.rev).cap += c;
                    v = u;
                }
                long delta = -potential[s];
                flow += c;
                totalCost += c * delta;
                if (results.get(results.size() - 1)[1] == totalCost) {
                    results.remove(results.size() - 1);
                }
                results.add(new long[]{flow, totalCost});
            }
            return results;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] data = br.readLine().split(" ");
        int n = Integer.parseInt(data[0]);
        String[] aStr = br.readLine().split(" ");
        String[] bStr = br.readLine().split(" ");
        int a1 = Integer.parseInt(aStr[0]);
        int a2 = Integer.parseInt(aStr[1]);
        int a3 = Integer.parseInt(aStr[2]);
        int b1 = Integer.parseInt(bStr[0]);
        int b2 = Integer.parseInt(bStr[1]);
        int b3 = Integer.parseInt(bStr[2]);

        FlowGraph g = new FlowGraph(8);
        g.addEdge(0, 1, a1, 0);
        g.addEdge(0, 2, a2, 0);
        g.addEdge(0, 3, a3, 0);
        g.addEdge(4, 7, b1, 0);
        g.addEdge(5, 7, b2, 0);
        g.addEdge(6, 7, b3, 0);

        for (int i = 1; i <= 3; i++) {
            for (int j = 4; j <= 6; j++) {
                int cst = ((j - i) % 3 == 1) ? 1 : 0;
                g.addEdge(i, j, Integer.MAX_VALUE, cst);
            }
        }

        List<long[]> result = g.computeFlow(0, 7, (1L << 32) - 1);
        long ans1 = result.get(result.size() - 1)[0];
        long ans2 = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);
        System.out.println(ans1 + " " + ans2);
    }
}
